<template><span v-if="!interactive||!row.available" class="qnav-entry" :data-layout="layout" :class="{'is-disabled':!row.available,active}" :title="hint"><MenuIcon :row="row" :active="active"/><b v-if="layout==='rail'">{{label}}</b><span v-else>{{label}}</span><ClientIcon v-if="row.kind==='external'" name="arrowUpRight"/></span><a v-else-if="row.kind==='external'&&row.url&&!row.loginRequired" class="qnav-entry" :data-layout="layout" :class="{active}" :href="row.url" :target="row.openInNewTab?'_blank':undefined" rel="noopener noreferrer" :title="hint" @click="$emit('navigate')"><MenuIcon :row="row" :active="active"/><b v-if="layout==='rail'">{{label}}</b><span v-else>{{label}}</span><ClientIcon name="arrowUpRight"/></a><router-link v-else class="qnav-entry" :data-layout="layout" :class="{active}" :to="row.path" :target="row.openInNewTab?'_blank':undefined" rel="noopener noreferrer" :title="hint" :aria-current="active?'page':undefined" @click="$emit('navigate')"><MenuIcon :row="row" :active="active"/><b v-if="layout==='rail'">{{label}}</b><span v-else>{{label}}</span><ClientIcon v-if="row.loginRequired" name="lock"/></router-link></template>
<script setup>
import{computed}from'vue';import{currentLang}from'../../i18n/index.js';import{menuLabel,menuHint}from'../../lib/navigation.js';import{navigationText}from'../../i18n/navigation-messages.js';import MenuIcon from'./MenuIcon.vue';import ClientIcon from'../reference/ClientIcon.vue';
const props=defineProps({row:{type:Object,required:true},interactive:{type:Boolean,default:true},active:Boolean,layout:{type:String,default:'row'}});defineEmits(['navigate']);const label=computed(()=>menuLabel(props.row,currentLang.value)),hint=computed(()=>props.row.available?menuHint(props.row,currentLang.value)||label.value:navigationText(currentLang.value,'入口暂时不可用'));
</script>
